INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'press', 'v.', '/pres/', '按;压', 'You only need to press a button to start the machine.', '你只需按一个按钮就能启动机器。', 'The World of Science', 1, 0, 'senior', 'wordlist', 'required3', 'U3', 'press a button', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shoot', 'v.', '/ʃuːt/', '射出(光线等);放射', 'The new laser can shoot a thin beam of light at the target.', '这种新激光能向目标射出一束细光。', 'The World of Science', 2, 0, 'senior', 'wordlist', 'required3', 'U3', 'shoot out', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gunpowder', 'n.', '/ˈɡʌnˌpaʊdə/', '火药', 'Gunpowder was one of the four great inventions of ancient China.', '火药是中国古代四大发明之一。', 'The World of Science', 3, 0, 'senior', 'wordlist', 'required3', 'U3', 'the invention of gunpowder', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'compass', 'n.', '/ˈkʌmpəs/', '指南针;罗盘', 'Sailors used a compass to find their way far out at sea.', '水手用指南针在远海中辨别方向。', 'The World of Science', 4, 0, 'senior', 'wordlist', 'required3', 'U3', 'use a compass', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'virtual', 'adj.', '/ˈvɜːtʃuəl/', '虚拟的;模拟的', 'Many games now create a virtual world that looks almost real.', '如今许多游戏创造出几乎逼真的虚拟世界。', 'The World of Science', 5, 0, 'senior', 'wordlist', 'required3', 'U3', 'virtual reality', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'virtual reality', 'n.', '/ˌvɜːtʃuəl riˈæləti/', '虚拟现实', 'Virtual reality has been used to train new doctors safely.', '虚拟现实已被用来安全地培训新医生。', 'The World of Science', 6, 0, 'senior', 'wordlist', 'required3', 'U3', 'virtual reality', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wearable tech', 'n.', '/ˈweərəbl tek/', '可穿戴技术', 'Wearable tech such as smart watches has become very popular.', '智能手表等可穿戴技术已变得非常流行。', 'The World of Science', 7, 0, 'senior', 'wordlist', 'required3', 'U3', 'wearable tech', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flexible', 'adj.', '/ˈfleksɪbl/', '易弯曲的;柔韧的', 'The new battery is thin and flexible, so it can bend easily.', '这种新电池又薄又柔韧,可以轻松弯曲。', 'The World of Science', 8, 0, 'senior', 'wordlist', 'required3', 'U3', 'a flexible battery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'battery', 'n.', '/ˈbætri/', '电池', 'A flexible battery can power a wearable device for days.', '一块柔性电池可以为可穿戴设备供电数天。', 'The World of Science', 9, 0, 'senior', 'wordlist', 'required3', 'U3', 'a flexible battery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'in addition', 'phr.', '/ɪn əˈdɪʃn/', '除此之外;另外', 'In addition, important advances have been made in medicine.', '除此之外,医学上也取得了重要进展。', 'The World of Science', 10, 0, 'senior', 'wordlist', 'required3', 'U3', 'in addition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'compute', 'v.', '/kəmˈpjuːt/', '计算', 'Powerful computers can compute millions of numbers each second.', '强大的计算机每秒能计算数百万个数字。', 'The World of Science', 11, 0, 'senior', 'wordlist', 'required3', 'U3', 'compute the result', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'capable', 'adj.', '/ˈkeɪpəbl/', '有能力的', 'The walking house is capable of moving to a safer place by itself.', '这座会走的房子能自行移动到更安全的地方。', 'The World of Science', 12, 0, 'senior', 'wordlist', 'required3', 'U3', 'be capable of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stuff', 'n.', '/stʌf/', '东西;物品', 'Impressive stuff like this has been made by a big team.', '这样令人惊叹的东西是由一个大团队制造的。', 'The World of Science', 13, 0, 'senior', 'wordlist', 'required3', 'U3', 'impressive stuff', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'desire', 'n.', '/dɪˈzaɪə/', '渴望;欲望', 'The desire to create new things drives every great inventor.', '创造新事物的渴望驱动着每一位伟大的发明家。', 'The World of Science', 14, 0, 'senior', 'wordlist', 'required3', 'U3', 'the desire to create', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'passive', 'adj.', '/ˈpæsɪv/', '被动的', 'In a passive sentence, the action is done to the subject.', '在被动句中,动作是施加在主语身上的。', 'The World of Science', 15, 0, 'senior', 'wordlist', 'required3', 'U3', 'the passive form', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'beyond', 'prep.', '/bɪˈjɒnd/', '无法……;超出;在……那边', 'Our lives may be changed beyond recognition by new technology.', '新技术可能把我们的生活改变得面目全非。', 'The World of Science', 16, 0, 'senior', 'wordlist', 'required3', 'U3', 'beyond recognition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'instance', 'n.', '/ˈɪnstəns/', '例子;实例', 'For instance, some restaurants have served 3D-printed food.', '例如,有些餐馆已供应过3D打印的食物。', 'The World of Science', 17, 0, 'senior', 'wordlist', 'required3', 'U3', 'for instance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'significant', 'adj.', '/sɪɡˈnɪfɪkənt/', '重要的;影响深远的', 'Significant advances have been made in solar technology.', '太阳能技术取得了重大进步。', 'The World of Science', 18, 0, 'senior', 'wordlist', 'required3', 'U3', 'a significant advance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'injure', 'v.', '/ˈɪndʒə/', '使受伤;弄伤', 'A turtle that had been injured in a fire was given a new shell.', '一只在火灾中受伤的乌龟得到了一个新壳。', 'The World of Science', 19, 0, 'senior', 'wordlist', 'required3', 'U3', 'be injured in a fire', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chemist', 'n.', '/ˈkemɪst/', '化学家', 'A chemist studies what different materials are made of.', '化学家研究各种材料的构成。', 'The World of Science', 20, 0, 'senior', 'wordlist', 'required3', 'U3', 'a famous chemist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'astronomer', 'n.', '/əˈstrɒnəmə/', '天文学家', 'An astronomer studies the stars, planets and other objects in space.', '天文学家研究恒星、行星等太空中的天体。', 'The World of Science', 21, 0, 'senior', 'wordlist', 'required3', 'U3', 'a young astronomer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'biologist', 'n.', '/baɪˈɒlədʒɪst/', '生物学家', 'A biologist studies living things such as plants and animals.', '生物学家研究植物和动物等生物。', 'The World of Science', 22, 0, 'senior', 'wordlist', 'required3', 'U3', 'a leading biologist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'accurate', 'adj.', '/ˈækjʊrət/', '精确的;准确的', 'The old calendar was almost as accurate as the modern one.', '这部古老的历法几乎和现代历法一样精确。', 'The World of Science', 23, 0, 'senior', 'wordlist', 'required3', 'U3', 'an accurate calendar', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'minor', 'adj.', '/ˈmaɪnə/', '小的;次要的', 'A minor planet was named after the great scientist.', '一颗小行星以这位伟大科学家的名字命名。', 'The World of Science', 24, 0, 'senior', 'wordlist', 'required3', 'U3', 'a minor planet', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'origin', 'n.', '/ˈɒrɪdʒɪn/', '起源;起因', 'Darwin''s famous book explains the origin of different species.', '达尔文的名著解释了不同物种的起源。', 'The World of Science', 25, 0, 'senior', 'wordlist', 'required3', 'U3', 'the origin of species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'species', 'n.', '/ˈspiːʃiːz/', '物种', 'Many species change very slowly over a long time.', '许多物种在漫长的时间里非常缓慢地变化。', 'The World of Science', 26, 0, 'senior', 'wordlist', 'required3', 'U3', 'a new species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stream', 'n.', '/striːm/', '小河;小溪', 'The scientist studied more than a thousand rivers and streams.', '这位科学家研究了一千多条河流和小溪。', 'The World of Science', 27, 0, 'senior', 'wordlist', 'required3', 'U3', 'rivers and streams', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extraordinary', 'adj.', '/ɪkˈstrɔːdnri/', '非凡的;出色的', 'Marie Curie did extraordinary work and won the Nobel Prize twice.', '玛丽·居里做出了非凡的工作,两次获得诺贝尔奖。', 'The World of Science', 28, 0, 'senior', 'wordlist', 'required3', 'U3', 'extraordinary work', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'brilliant', 'adj.', '/ˈbrɪljənt/', '聪颖的;才华横溢的', 'She was regarded as a brilliant chemist by everyone in the lab.', '实验室里的每个人都把她视为一位才华横溢的化学家。', 'The World of Science', 29, 0, 'senior', 'wordlist', 'required3', 'U3', 'a brilliant mind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'theory', 'n.', '/ˈθɪəri/', '学说;理论', 'A falling apple is said to have led Newton to his theory of gravity.', '据说一个落下的苹果让牛顿想到了万有引力理论。', 'The World of Science', 30, 0, 'senior', 'wordlist', 'required3', 'U3', 'the theory of gravity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mental', 'adj.', '/ˈmentl/', '精神的;心理的', 'Alzheimer''s is a common mental disease among older people.', '阿尔茨海默病是老年人中常见的一种精神疾病。', 'The World of Science', 31, 0, 'senior', 'wordlist', 'required3', 'U3', 'a mental disease', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cure', 'n.', '/kjʊə/', '药剂;疗法', 'At present there is still no cure for this disease.', '目前这种疾病仍无治愈的方法。', 'The World of Science', 32, 0, 'senior', 'wordlist', 'required3', 'U3', 'no cure for', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'draft', 'v.', '/drɑːft/', '起草;草拟', 'Franklin helped to draft the Declaration of Independence.', '富兰克林参与起草了《独立宣言》。', 'The World of Science', 33, 0, 'senior', 'wordlist', 'required3', 'U3', 'draft a document', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'declaration', 'n.', '/ˌdekləˈreɪʃn/', '声明;宣告', 'The Declaration of Independence has been read by millions of people.', '《独立宣言》已被数百万人阅读。', 'The World of Science', 34, 0, 'senior', 'wordlist', 'required3', 'U3', 'a declaration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'experiment', 'n.', '/ɪkˈsperɪmənt/', '(科学)实验', 'Franklin''s experiment with lightning made him famous.', '富兰克林的闪电实验使他声名远扬。', 'The World of Science', 35, 0, 'senior', 'wordlist', 'required3', 'U3', 'carry out an experiment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lightning', 'n.', '/ˈlaɪtnɪŋ/', '闪电', 'A flash of lightning hit the kite during the storm.', '一道闪电在暴风雨中击中了风筝。', 'The World of Science', 36, 0, 'senior', 'wordlist', 'required3', 'U3', 'a flash of lightning', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fiction', 'n.', '/ˈfɪkʃn/', '虚构的事;小说', 'New research suggests the story may be fiction rather than fact.', '新研究表明这个故事也许是虚构而非事实。', 'The World of Science', 37, 0, 'senior', 'wordlist', 'required3', 'U3', 'fiction or fact', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'metal', 'n.', '/ˈmetl/', '金属', 'A metal key was attached to the wet string of the kite.', '一把金属钥匙被系在风筝湿润的线上。', 'The World of Science', 38, 0, 'senior', 'wordlist', 'required3', 'U3', 'a metal key', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attach', 'v.', '/əˈtætʃ/', '系;绑;贴', 'A key was attached to the string so the electricity could pass down.', '钥匙被系在线上,这样电流就能传下来。', 'The World of Science', 39, 0, 'senior', 'wordlist', 'required3', 'U3', 'attach to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flash', 'n.', '/flæʃ/', '闪光', 'A bright flash of light suddenly appeared in the dark sky.', '一道亮光突然出现在黑暗的天空中。', 'The World of Science', 40, 0, 'senior', 'wordlist', 'required3', 'U3', 'a flash of light', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'conduct', 'v.', '/kənˈdʌkt/', '传导(热、电)', 'The wet string can conduct electricity from the sky to the key.', '湿绳能把电从天空传导到钥匙上。', 'The World of Science', 41, 0, 'senior', 'wordlist', 'required3', 'U3', 'conduct electricity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'scientific', 'adj.', '/ˌsaɪənˈtɪfɪk/', '科学(上)的', 'Scientific experiments help us to find out the truth.', '科学实验帮助我们查明真相。', 'The World of Science', 42, 0, 'senior', 'wordlist', 'required3', 'U3', 'a scientific approach', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'entirely', 'adv.', '/ɪnˈtaɪəli/', '完全地;彻底地', 'Scientists found that the old story was not entirely true.', '科学家发现那个旧故事并不完全属实。', 'The World of Science', 43, 0, 'senior', 'wordlist', 'required3', 'U3', 'not entirely true', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gravity', 'n.', '/ˈɡrævəti/', '重力;引力', 'Gravity is the force that pulls a falling apple to the ground.', '引力是把落下的苹果拉向地面的力。', 'The World of Science', 44, 0, 'senior', 'wordlist', 'required3', 'U3', 'the force of gravity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'account', 'n.', '/əˈkaʊnt/', '记述;描述', 'More than one account of the experiment has been written.', '关于这个实验已有不止一种记述。', 'The World of Science', 45, 0, 'senior', 'wordlist', 'required3', 'U3', 'an account of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'proof', 'n.', '/pruːf/', '证明;证据', 'There is no proof that the apple hit Newton on the head.', '没有证据表明苹果砸到了牛顿的头上。', 'The World of Science', 46, 0, 'senior', 'wordlist', 'required3', 'U3', 'no proof that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'procedure', 'n.', '/prəˈsiːdʒə/', '程序;步骤', 'Follow each step of the procedure carefully during the experiment.', '做实验时请仔细遵循每一个步骤。', 'The World of Science', 47, 0, 'senior', 'wordlist', 'required3', 'U3', 'follow the procedure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'natural selection', 'n.', '/ˌnætʃrəl sɪˈlekʃn/', '自然选择', 'Darwin explained how species change through natural selection.', '达尔文解释了物种如何通过自然选择而演变。', 'The World of Science', 48, 0, 'senior', 'wordlist', 'required3', 'U3', 'natural selection', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u3.01', '①现在完成被动语态基本形式(have/has been + 过去分词)', 'A2', 10, '外研社版必修第三册 U3 — 主语是动作的承受者、且有现在完成时间标志(recently / so far / over the past years / by + 施动者)时,用 have/has been + 过去分词。', 1, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u3.02', '②现在完成被动 vs 现在完成主动(主语承受 or 发出动作)', 'A2', 10, '外研社版必修第三册 U3 — 看主语是动作的承受者还是发出者:承受者(常带 by 施动者、空后无宾语)用 have/has been done;发出者(空后跟宾语)用 have/has done。', 2, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u3.03', '③现在完成被动 vs 一般现在/一般过去被动(时间标志定时态)', 'A2', 10, '外研社版必修第三册 U3 — 四个选项都是被动,但时态不同;already / so far / up to now / by now 等标志要求现在完成被动 have/has been done,而非 is/are done 或 was/were done。', 3, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'A great many new inventions ____ by scientists over the past few years.', 'have been made', 'have made', 'are making', 'make', 'A', '主语 inventions 是动作承受者,又有 over the past few years → have been + made。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Recently, 3D printers ____ by doctors to create replacement hearts.', 'have used', 'have been used', 'are using', 'use', 'B', 'printers 被使用、有 recently → have been used。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Since 2010, several new medicines ____ by researchers for this illness.', 'have developed', 'develop', 'have been developed', 'are developing', 'C', 'medicines 被研发、since 2010 → have been developed。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'So far, an intelligent walking house ____ by a clever young team.', 'has built', 'is building', 'builds', 'has been built', 'D', 'house 被建造、so far → has been built。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Up to now, only part of the energy problem ____ by engineers.', 'has been solved', 'has solved', 'solves', 'is solving', 'A', 'problem 被解决、up to now → has been solved。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'In recent years, the flexible battery ____ greatly by engineers.', 'has improved', 'has been improved', 'improves', 'is improving', 'B', 'battery 被改进、有 by engineers 施动者 → has been improved。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Just now, a strange new instrument ____ by the inventor.', 'has designed', 'designs', 'has been designed', 'is designing', 'C', 'instrument 被设计、by the inventor → has been designed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Over the past decade, many electric cars ____ by Chinese companies.', 'have produced', 'produce', 'are producing', 'have been produced', 'D', 'cars 被生产、over the past decade → have been produced。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Lately, a smart watch for blind people ____ by a small start-up.', 'has been created', 'has created', 'creates', 'is creating', 'A', 'watch 被创造、lately + by 短语 → has been created。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'This year, a cheaper solar panel ____ by the research centre.', 'has introduced', 'has been introduced', 'introduces', 'is introducing', 'B', 'panel 被推出、by the research centre → has been introduced。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Already, the new heart pump ____ by the hospital team.', 'has tested', 'tests', 'has been tested', 'is testing', 'C', 'pump 被测试、already + by 短语 → has been tested。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'For many years, the compass ____ by sailors all over the world.', 'has used', 'uses', 'is using', 'has been used', 'D', 'compass 被使用、for many years + by 短语 → has been used。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Since last spring, the broken robot ____ by the students.', 'has been repaired', 'has repaired', 'repairs', 'is repairing', 'A', 'robot 被修理、since last spring → has been repaired。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Recently, two damaged machines ____ by the workers.', 'have replaced', 'have been replaced', 'replace', 'are replacing', 'B', 'machines 被更换、recently + by 短语 → have been replaced。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'So far, the old experiment ____ by several scientists.', 'has examined', 'examines', 'has been examined', 'is examining', 'C', 'experiment 被检验、so far + by 短语 → has been examined。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Over the years, the inventor''s story ____ by many writers.', 'has recorded', 'records', 'is recording', 'has been recorded', 'D', 'story 被记述、over the years + by 短语 → has been recorded。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'This month, the team''s results ____ by a famous science magazine.', 'have been published', 'have published', 'publish', 'are publishing', 'A', 'results 被发表、by 短语 → have been published。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Recently, a minor planet ____ after the great scientist.', 'has named', 'has been named', 'names', 'is naming', 'B', 'planet 被命名、recently → has been named。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Up to now, thousands of stars ____ by that astronomer.', 'have studied', 'study', 'have been studied', 'are studying', 'C', 'stars 被研究、up to now + by 短语 → have been studied。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.01'), 'Since the fire, a new 3D-printed shell ____ to the injured turtle.', 'has given', 'gives', 'is giving', 'has been given', 'D', 'shell 被给予、since the fire → has been given。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'So far, many great inventions ____ by ordinary people, not just experts.', 'have been made', 'have made', 'are made', 'make', 'A', '主语 inventions 是承受者、带 by 短语 → have been made。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'So far, ordinary people ____ many great inventions, not just experts.', 'have been made', 'have made', 'are making', 'makes', 'B', '主语 people 是发出者、空后跟宾语 inventions → 主动 have made。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Recently, the old theory ____ by more than one scientist.', 'has questioned', 'is questioned', 'has been questioned', 'questions', 'C', 'theory 是承受者、带 by 短语 → has been questioned。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Recently, more than one scientist ____ the old theory.', 'has been questioned', 'is questioning', 'question', 'has questioned', 'D', 'scientist 是发出者、空后跟宾语 theory → 主动 has questioned。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Up to now, the experiment ____ by students all over the country.', 'has been repeated', 'has repeated', 'is repeated', 'repeats', 'A', 'experiment 是承受者、带 by 短语 → has been repeated。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Up to now, students all over the country ____ the experiment.', 'have been repeated', 'have repeated', 'are repeating', 'repeats', 'B', 'students 是发出者、空后跟宾语 experiment → 主动 have repeated。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'For centuries, the compass ____ by sailors crossing the sea.', 'has used', 'is used', 'has been used', 'uses', 'C', 'compass 是承受者、带 by 短语 → has been used。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'For centuries, sailors crossing the sea ____ the compass.', 'have been used', 'are using', 'uses', 'have used', 'D', 'sailors 是发出者、空后跟宾语 compass → 主动 have used。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Lately, replacement body parts ____ by clever 3D printers.', 'have been produced', 'have produced', 'are produced', 'produce', 'A', 'parts 是承受者、带 by 短语 → have been produced。', 2, 9, 'mcq');
