INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'This year, a new energy car ____ by that young engineer.', 'has designed', 'is designed', 'has been designed', 'designs', 'C', 'car 是承受者、带 by 短语 → has been designed。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'This year, that young engineer ____ a new energy car.', 'has been designed', 'is designing', 'design', 'has designed', 'D', 'engineer 是发出者、空后跟宾语 car → 主动 has designed。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Already, the patient''s heart problem ____ by the doctors.', 'has been treated', 'has treated', 'is treated', 'treats', 'A', 'problem 是承受者、带 by 短语 → has been treated。', 2, 13, 'mcq');
