INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.02'), 'Over time, the truth about the apple ____ by several writers.', 'has been doubted', 'has doubted', 'is doubted', 'doubts', 'A', 'truth 是承受者、带 by 短语 → has been doubted。', 2, 17, 'mcq');
