INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'By now, the new vaccine ____ to thousands of patients.', 'has been given', 'is given', 'was given', 'will be given', 'A', 'by now 表到目前为止 → 现在完成被动 has been given。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Over the past ten years, many electric cars ____ in this city.', 'are produced', 'have been produced', 'were produced', 'will be produced', 'B', 'over the past ten years → 现在完成被动 have been produced。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'So far, the broken telescope ____ twice this year.', 'is repaired', 'was repaired', 'has been repaired', 'will be repaired', 'C', 'so far → 现在完成被动 has been repaired。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Already, the team''s results ____ in a famous journal.', 'are published', 'were published', 'will be published', 'have been published', 'D', 'already → 现在完成被动 have been published。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Up to now, the old theory ____ many times.', 'has been tested', 'is tested', 'was tested', 'will be tested', 'A', 'up to now → 现在完成被动 has been tested。', 2, 5, 'mcq');
