INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Recently, the famous experiment ____ by several teams.', 'is copied', 'was copied', 'has been copied', 'will be copied', 'C', 'recently → 现在完成被动 has been copied。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Lately, a great deal of money ____ on medical research.', 'is spent', 'was spent', 'will be spent', 'has been spent', 'D', 'lately → 现在完成被动 has been spent。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'In the last decade, much progress ____ in solar power.', 'has been made', 'is made', 'was made', 'will be made', 'A', 'in the last decade → 现在完成被动 has been made。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'This week, the damaged robot ____ at last.', 'is fixed', 'has been fixed', 'was fixed', 'will be fixed', 'B', 'this week + at last → 现在完成被动 has been fixed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Up to now, no time machine ____ anywhere in the world.', 'is invented', 'was invented', 'has been invented', 'will be invented', 'C', 'up to now → 现在完成被动 has been invented。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'So far, the new heart pump ____ on many patients.', 'is used', 'was used', 'will be used', 'has been used', 'D', 'so far → 现在完成被动 has been used。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'By now, the science museum ____ by millions of visitors.', 'has been visited', 'is visited', 'was visited', 'will be visited', 'A', 'by now → 现在完成被动 has been visited。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Recently, the rare planet ____ after a Chinese scientist.', 'is named', 'has been named', 'was named', 'will be named', 'B', 'recently → 现在完成被动 has been named。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Over the years, the inventor''s name ____ almost everywhere.', 'is heard', 'was heard', 'has been heard', 'will be heard', 'C', 'over the years → 现在完成被动 has been heard。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Already, the new calendar ____ across the whole country.', 'is introduced', 'was introduced', 'will be introduced', 'has been introduced', 'D', 'already → 现在完成被动 has been introduced。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Since the fire, the injured turtle ____ a 3D-printed shell.', 'has been given', 'is given', 'was given', 'will be given', 'A', 'since the fire → 现在完成被动 has been given。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Up to now, thousands of stars ____ through this telescope.', 'are studied', 'have been studied', 'were studied', 'will be studied', 'B', 'up to now → 现在完成被动 have been studied。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'Lately, several old machines ____ with safer ones.', 'are replaced', 'were replaced', 'have been replaced', 'will be replaced', 'C', 'lately → 现在完成被动 have been replaced。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U3' AND code='f3u3.03'), 'By now, the whole report ____ into three languages.', 'is translated', 'was translated', 'will be translated', 'has been translated', 'D', 'by now → 现在完成被动 has been translated。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The New Age of Invention', 'Many people believe that the great age of invention is over, but in fact we have entered an exciting new one. In the past, the world was changed by inventions such as gunpowder, printing and the compass in ancient China, and later by the steam engine and the telephone in the West. Today, however, most great inventions are based on technology. Advances in virtual reality, wearable tech and flexible batteries mean that new products appear almost every month. Important progress has also been made in medicine and environmental science, thanks to the growing power of computers. What has not changed is the human desire to think and to create. According to one writer, most inventions begin when a person notices a problem that needs a solution. As long as people keep asking questions, the age of invention will never truly come to an end.', '说明·我们正进入科技驱动的新发明时代', 144, '[{"q":"What is the writer''s main point?","answer":"A","options":["The age of invention is far from over.","Ancient inventions were better than modern ones.","Computers have stopped people from inventing.","Only Western countries can invent things."],"explanation":"全文主旨''we have entered an exciting new one''的转述。"},{"q":"What are most great inventions based on today?","answer":"B","options":["Gunpowder and printing.","Technology.","The steam engine.","Old farming tools."],"explanation":"原文''most great inventions are based on technology''。"},{"q":"According to the writer, how do most inventions begin?","answer":"A","options":["When a problem needs to be solved.","When the government orders them.","When old machines break down.","When money runs out."],"explanation":"末段''begin when a person notices a problem that needs a solution''的转述。"}]'::jsonb, '[{"word":"advance","cn":"进展;进步"},{"word":"desire","cn":"渴望"}]'::jsonb, 2, 'required3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'When Machines Print Body Parts', 'Within the next eighty years, our lives may be changed beyond recognition by 3D printing. This technology has already affected many areas, right down to the food on our plates; in London, some restaurants have served 3D-printed hamburgers to their customers. Yet the most significant success so far has been in medicine. Using special printers, scientists have made human body parts, including a beating heart and strong new bones. These parts can be designed to fit each patient exactly, which makes operations safer. It is not only humans who benefit. In Brazil, a turtle that had been hurt in a forest fire was given a new 3D-printed shell, and soon it could swim again. Doctors believe that, in the future, fewer patients will have to wait for a suitable donor, because the parts they need will simply be printed in a lab.', '说明·3D打印在医疗中的应用', 142, '[{"q":"Where has 3D printing had its most important success?","answer":"B","options":["In cooking only.","In medicine.","In space travel.","In farming."],"explanation":"原文''the most significant success so far has been in medicine''。"},{"q":"Why is a printed body part safer for an operation?","answer":"C","options":["It is much cheaper than food.","It is printed in a restaurant.","It can be made to fit the patient exactly.","It is larger than a normal part."],"explanation":"原文''designed to fit each patient exactly, which makes operations safer''的转述。"},{"q":"What happened to the turtle in Brazil?","answer":"D","options":["It learned to fly.","It was sent to London.","It was never found.","It received a new printed shell."],"explanation":"原文''was given a new 3D-printed shell''的转述。"}]'::jsonb, '[{"word":"donor","cn":"捐献者"},{"word":"significant","cn":"重要的"}]'::jsonb, 2, 'required3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The House That Walks', 'Imagine a house that can pick itself up and move to a new place. Thanks to advances in technology, such a house has now been built. The intelligent walking house uses GPS to find its way, while computers control its six metal legs. If the weather turns bad, or if the owners simply want a different view, the house can slowly walk to somewhere better. Because it is powered by the sun, it does not harm the environment, and it produces almost no waste. The idea may sound like science fiction, but every part of it depends on real science that already exists. Engineers say that homes like this could one day help people who live in places where floods or storms are common. When the danger comes, the house will not be left behind; instead, it will quietly carry its owners to safety.', '说明·能自行移动的智能房屋', 144, '[{"q":"How does the walking house find its way?","answer":"A","options":["By using GPS.","By asking neighbours.","By following a paper map.","By guessing."],"explanation":"原文''uses GPS to find its way''。"},{"q":"Why is the house friendly to the environment?","answer":"B","options":["It is made of paper.","It runs on solar power.","It never moves at all.","It burns coal."],"explanation":"原文''powered by the sun, it does not harm the environment''的转述。"},{"q":"Who might such houses help in the future?","answer":"C","options":["Only rich tourists.","People who dislike science.","People in places with floods or storms.","Drivers on long trips."],"explanation":"末段''help people who live in places where floods or storms are common''的转述。"}]'::jsonb, '[{"word":"GPS","cn":"全球定位系统"},{"word":"waste","cn":"废物"}]'::jsonb, 2, 'required3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Franklin''s Experiment: How True?', 'Benjamin Franklin''s experiment with lightning has introduced generations of children to science. The famous story says that in 1752 he flew a kite during a storm, with a metal key tied to the wet string. When lightning struck, electricity was carried down the string, and Franklin touched the key to prove that lightning is a form of electricity. For many years this story has been taught in schools, and children have been amazed by his courage. New research, however, suggests that the tale may be more fiction than fact. Although it has been proved that the experiment really took place, scientists agree that if Franklin had truly touched the key, the shock would have killed him. The lesson is an important one. In science, facts should be tested by experiment and proof, and we should not believe everything we read, even when it makes a wonderful story.', '议论·富兰克林闪电实验的真相', 147, '[{"q":"What did Franklin''s experiment try to prove?","answer":"D","options":["That kites are dangerous toys.","That metal keys are valuable.","That storms never happen.","That lightning is really a kind of electricity."],"explanation":"原文''to prove that lightning is a form of electricity''的转述。"},{"q":"Why do scientists doubt the famous story?","answer":"A","options":["He would probably have died from the shock.","Franklin never lived in America.","Kites cannot fly in storms.","Electricity did not exist then."],"explanation":"原文''if Franklin had truly touched the key, the shock would have killed him''的转述。"},{"q":"What lesson does the writer want readers to learn?","answer":"B","options":["Good stories are always true.","Facts should be tested, not simply believed.","Science is a waste of time.","Children should not study Franklin."],"explanation":"末段''facts should be tested by experiment and proof''的转述。"}]'::jsonb, '[{"word":"shock","cn":"电击"},{"word":"courage","cn":"勇气"}]'::jsonb, 2, 'required3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Careers in Science', 'The world of science offers many different careers, and the words we use for them often come from the subjects themselves. A person who studies living things is called a biologist, while someone who studies the stars and planets is an astronomer. A chemist works with the materials that everything is made of, and a physicist tries to understand energy and forces such as gravity. History is full of brilliant examples. Charles Darwin, a famous biologist, explained how species change over time through natural selection. Marie Curie, working as both a physicist and a chemist, was awarded the Nobel Prize twice for her extraordinary research. What these scientists shared was not only great ability but also patience and curiosity. They were not afraid to ask difficult questions, and they kept working even when the answers were slow to come. Their stories show that science needs both a clever mind and a brave heart.', '说明·不同的科学职业', 153, '[{"q":"What does an astronomer study?","answer":"C","options":["Living animals.","Ancient languages.","The stars and planets.","City traffic."],"explanation":"原文''someone who studies the stars and planets is an astronomer''。"},{"q":"What was Marie Curie awarded twice?","answer":"D","options":["A new planet.","A teaching job.","A sports medal.","The Nobel Prize."],"explanation":"原文''awarded the Nobel Prize twice''。"},{"q":"According to the writer, what did these scientists share?","answer":"A","options":["Patience and curiosity.","A dislike of questions.","A fear of hard work.","The same birthday."],"explanation":"原文''patience and curiosity''的转述。"}]'::jsonb, '[{"word":"physicist","cn":"物理学家"},{"word":"curiosity","cn":"好奇心"}]'::jsonb, 2, 'required3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'An Invention to Remember', 'Alzheimer''s disease is a brain illness that causes problems with memory and thinking, and most of the people who suffer from it are over sixty-five. At present there is no cure, but clever inventions can still make daily life safer. One young inventor named Kenneth designed a small device after watching his own grandmother, who has Alzheimer''s, lose her way near home. The device is worn like a watch. If the person wearing it walks too far from home, a signal is sent to a family member''s mobile phone, rather like an alarm. In this way, help can arrive before the person becomes lost or frightened. Kenneth says the idea came from love, not from money. He hopes that, as computers grow more powerful, many more tools like this will be created to help people who are living with the disease and the families who care for them.', '记叙·帮助阿尔茨海默病患者的小发明', 148, '[{"q":"Who mainly suffers from Alzheimer''s disease?","answer":"B","options":["Young children.","People over sixty-five.","Only scientists.","Newborn babies."],"explanation":"原文''most of the people who suffer from it are over sixty-five''的转述。"},{"q":"What does Kenneth''s device do when the wearer walks too far?","answer":"C","options":["It stops the person from moving.","It plays loud music in the street.","It sends a signal to a family member''s phone.","It calls the police station."],"explanation":"原文''a signal is sent to a family member''s mobile phone''的转述。"},{"q":"Where did Kenneth get the idea for his invention?","answer":"D","options":["From a science magazine.","From a large company.","From a school exam.","From love for his grandmother."],"explanation":"原文''the idea came from love, not from money''的转述。"}]'::jsonb, '[{"word":"device","cn":"装置"},{"word":"signal","cn":"信号"}]'::jsonb, 2, 'required3', 'U3', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'The Wheel and the Car', 'Most inventions begin when someone notices a (1)____ that needs solving. Long ago, moving heavy loads was very hard, so people invented the (2)____. Much later, this simple idea (3)____ into the car. Today cars are everywhere, but they also (4)____ pollution and use a lot of energy. For this (5)____, engineers have worked hard to build cleaner cars. New energy vehicles are now (6)____ by many companies around the world. They are (7)____ by electricity instead of petrol, so they are kinder to the (8)____. Some people think the great age of invention is (9)____, but they are wrong. As long as we keep (10)____ questions, new ideas will always appear.', 112, 2, '[{"q":"1","answer":"A","options":["problem","holiday","song","garden"],"explanation":"a problem that needs solving 待解决的问题。"},{"q":"2","answer":"B","options":["river","wheel","story","market"],"explanation":"invented the wheel 发明了轮子。"},{"q":"3","answer":"C","options":["ate","sold","developed","lost"],"explanation":"developed into the car 发展成汽车。"},{"q":"4","answer":"D","options":["enjoy","forget","sing","cause"],"explanation":"cause pollution 造成污染。"},{"q":"5","answer":"A","options":["reason","weather","noise","price"],"explanation":"for this reason 因此。"},{"q":"6","answer":"B","options":["eaten","produced","sung","thrown"],"explanation":"are produced by companies 被公司生产。"},{"q":"7","answer":"C","options":["eaten","sold","powered","hidden"],"explanation":"powered by electricity 由电力驱动。"},{"q":"8","answer":"D","options":["music","holiday","price","environment"],"explanation":"kinder to the environment 对环境更友好。"},{"q":"9","answer":"A","options":["over","hungry","green","loud"],"explanation":"the age is over 时代结束了。"},{"q":"10","answer":"B","options":["eating","asking","sleeping","selling"],"explanation":"keep asking questions 不断提问。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'The Four Great Inventions', 'Ancient China gave the world four great (1)____: gunpowder, papermaking, printing and the compass. Each of them (2)____ the world deeply. The compass, for (3)____, allowed sailors to find their way far from (4)____. Printing made books cheaper, so knowledge could be (5)____ more widely. These inventions were not made by a single (6)____, but by many people over time. Even today, the compass is still (7)____ in ships and planes. When we study the past, we (8)____ that invention has always been part of human (9)____. The desire to (10)____ is something all of us share.', 97, 2, '[{"q":"1","answer":"C","options":["holidays","gardens","inventions","prices"],"explanation":"four great inventions 四大发明。"},{"q":"2","answer":"D","options":["ate","sold","lost","changed"],"explanation":"changed the world 改变了世界。"},{"q":"3","answer":"A","options":["instance","sale","sleep","noise"],"explanation":"for instance 例如。"},{"q":"4","answer":"B","options":["music","land","price","song"],"explanation":"far from land 远离陆地。"},{"q":"5","answer":"C","options":["eaten","sung","shared","thrown"],"explanation":"could be shared 能被分享。"},{"q":"6","answer":"D","options":["river","garden","price","person"],"explanation":"a single person 一个人。"},{"q":"7","answer":"A","options":["used","eaten","sold","hidden"],"explanation":"is still used 仍被使用。"},{"q":"8","answer":"B","options":["sell","learn","sleep","throw"],"explanation":"we learn that 我们懂得。"},{"q":"9","answer":"C","options":["weather","noise","history","price"],"explanation":"human history 人类历史。"},{"q":"10","answer":"D","options":["sleep","sell","lose","create"],"explanation":"the desire to create 创造的渴望。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'A Young Inventor', 'My cousin Tom is only seventeen, but he is already a young (1)____. Last year he joined a small (2)____ of students who love science. Together they (3)____ a cheap robot that can help blind people cross the road. At first their robot did not (4)____ well, and many parts had to be (5)____ again and again. Tom almost wanted to give (6)____, but his teammates encouraged him to keep trying. Finally, after months of hard (7)____, the robot worked. Tom says that no great thing is ever done by one person (8)____. Most modern inventions are created by big (9)____ in which everyone shares ideas. He is proud to be (10)____ of such a group.', 116, 2, '[{"q":"1","answer":"A","options":["inventor","farmer","singer","driver"],"explanation":"a young inventor 年轻发明家。"},{"q":"2","answer":"B","options":["river","team","price","song"],"explanation":"a small team 一个小团队。"},{"q":"3","answer":"C","options":["ate","sold","built","lost"],"explanation":"built a robot 制造了机器人。"},{"q":"4","answer":"D","options":["sing","sleep","eat","work"],"explanation":"did not work well 运转不好。"},{"q":"5","answer":"A","options":["changed","eaten","sung","thrown"],"explanation":"had to be changed 不得不更换。"},{"q":"6","answer":"B","options":["in","up","off","out"],"explanation":"give up 放弃。"},{"q":"7","answer":"C","options":["weather","music","effort","price"],"explanation":"hard effort 努力。"},{"q":"8","answer":"D","options":["happy","green","loud","alone"],"explanation":"by one person alone 仅靠一人。"},{"q":"9","answer":"A","options":["teams","gardens","prices","songs"],"explanation":"big teams 大团队。"},{"q":"10","answer":"B","options":["price","part","noise","song"],"explanation":"be part of 成为……的一员。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'The Story of the Telephone', 'The telephone is one of the most important (1)____ in history. It was (2)____ by Alexander Graham Bell in 1876. Bell was interested in sound because his mother and his wife were (3)____ to hear well. He wanted to build a machine that could (4)____ the human voice along a wire. After many (5)____, the first words were finally sent from one room to (6)____. Since that day, the telephone has been (7)____ by billions of people all over the world. It has completely (8)____ the way we live and work. Of course, the phones we use today look nothing like Bell''s first (9)____. Yet the basic idea behind them is still the (10)____.', 114, 2, '[{"q":"1","answer":"C","options":["holidays","gardens","inventions","prices"],"explanation":"important inventions 重要发明。"},{"q":"2","answer":"D","options":["eaten","sung","thrown","invented"],"explanation":"was invented by 由……发明。"},{"q":"3","answer":"A","options":["unable","happy","green","loud"],"explanation":"unable to hear well 听不清。"},{"q":"4","answer":"B","options":["sleep","carry","sell","lose"],"explanation":"carry the voice 传送声音。"},{"q":"5","answer":"C","options":["songs","prices","tries","gardens"],"explanation":"after many tries 多次尝试后。"},{"q":"6","answer":"D","options":["music","price","noise","another"],"explanation":"from one room to another 从一间到另一间。"},{"q":"7","answer":"A","options":["used","eaten","sung","thrown"],"explanation":"has been used by 被使用。"},{"q":"8","answer":"B","options":["eaten","changed","sold","hidden"],"explanation":"has changed the way 改变了方式。"},{"q":"9","answer":"C","options":["river","song","model","price"],"explanation":"Bell''s first model 贝尔最早的型号。"},{"q":"10","answer":"D","options":["hungry","loud","green","same"],"explanation":"still the same 仍然相同。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'Marie Curie', 'Marie Curie was one of the most (1)____ scientists in history. She was born in Poland but did most of her (2)____ in France. For years she worked in a cold, poor (3)____, studying a strange new material. Her research was so (4)____ that she was awarded the Nobel Prize, not once but (5)____. Sadly, the very material she studied slowly (6)____ her health. Even so, she never (7)____ to stop her work. Today her discoveries are still (8)____ by doctors to treat serious illnesses. Marie Curie showed that a (9)____ mind and a brave heart can change the world. Her story has (10)____ many young women to become scientists.', 110, 2, '[{"q":"1","answer":"A","options":["famous","hungry","loud","green"],"explanation":"the most famous scientists 最著名的科学家。"},{"q":"2","answer":"B","options":["weather","research","music","price"],"explanation":"did her research 做研究。"},{"q":"3","answer":"C","options":["river","song","lab","garden"],"explanation":"a poor lab 简陋的实验室。"},{"q":"4","answer":"D","options":["hungry","loud","green","significant"],"explanation":"so significant that 如此重要。"},{"q":"5","answer":"A","options":["twice","slowly","sadly","loudly"],"explanation":"not once but twice 不止一次,而是两次。"},{"q":"6","answer":"B","options":["ate","harmed","sold","lost"],"explanation":"harmed her health 损害了她的健康。"},{"q":"7","answer":"C","options":["ate","sold","chose","lost"],"explanation":"never chose to stop 从未选择停下。"},{"q":"8","answer":"D","options":["eaten","sung","thrown","used"],"explanation":"are still used 仍被使用。"},{"q":"9","answer":"A","options":["brilliant","hungry","loud","green"],"explanation":"a brilliant mind 才华横溢的头脑。"},{"q":"10","answer":"B","options":["eaten","inspired","sold","hidden"],"explanation":"has inspired many 激励了许多人。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'Question Everything', 'Good scientists never stop (1)____ questions, even about ideas that everyone (2)____. Take the famous story of the apple that (3)____ on Newton''s head and led him to his theory of (4)____. For a long time, people simply (5)____ this story. Recently, however, more than one writer has (6)____ whether it is really true. They agree that Newton was (7)____ inspired by a falling apple, but there is no (8)____ that it hit him on the head. This does not make Newton less great. It only shows that, in science, every claim should be (9)____ by evidence. We should enjoy a good story, but we must not (10)____ everything we hear.', 111, 2, '[{"q":"1","answer":"C","options":["eating","sleeping","asking","selling"],"explanation":"stop asking questions 停止提问。"},{"q":"2","answer":"D","options":["eats","sells","loses","accepts"],"explanation":"everyone accepts 人人接受。"},{"q":"3","answer":"A","options":["fell","ate","sold","lost"],"explanation":"the apple that fell 落下的苹果。"},{"q":"4","answer":"B","options":["weather","gravity","music","price"],"explanation":"theory of gravity 万有引力理论。"},{"q":"5","answer":"C","options":["eaten","sung","believed","thrown"],"explanation":"simply believed 只是相信。"},{"q":"6","answer":"D","options":["eaten","sung","thrown","questioned"],"explanation":"has questioned whether 质疑是否。"},{"q":"7","answer":"A","options":["certainly","loudly","sadly","quickly"],"explanation":"certainly inspired 的确受到启发。"},{"q":"8","answer":"B","options":["weather","proof","music","song"],"explanation":"no proof that 没有证据。"},{"q":"9","answer":"C","options":["eaten","sung","tested","thrown"],"explanation":"should be tested by evidence 应由证据检验。"},{"q":"10","answer":"D","options":["sleep","sell","lose","believe"],"explanation":"must not believe everything 不可全信。"}]'::jsonb, 6, 'fltrp');
