INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write an Experiment Report(写一篇实验报告)', 'The Magic Bottle: How Air Pushes an Egg into a Bottle', '你在科学课上做了一个"魔法瓶"实验:把一个剥壳的熟鸡蛋放在瓶口,鸡蛋竟被吸进瓶里。请用英语写一篇约90词的实验报告,内容包括:① 实验目的;② 所用材料和主要步骤(多用被动语态,如 the shell was removed / hot water was poured in);③ 实验结果和你得出的结论。注意:步骤清楚、用词准确。', 'In a science class you did a ''magic bottle'' experiment: a peeled boiled egg was placed on the mouth of a bottle and was suddenly pulled inside. Write an experiment report (about 90 words) including: 1) the aim of the experiment; 2) the materials used and the main steps (use the passive voice, e.g. the shell was removed / hot water was poured in); 3) the result and the conclusion you draw.', '["说明实验目的(This experiment is designed to …)","列出材料和步骤、多用被动语态(First, the shell was removed …)","报告结果(After a few seconds, the egg was pulled inside.)","得出结论(I can draw the conclusion that …)"]'::jsonb, 70, 100, 'This experiment is designed to show how air pressure can push an egg into a bottle. To do this, I prepared a boiled egg, a glass bottle and some hot water. First, the shell of the egg was removed. Then hot water was poured into the bottle, shaken gently and poured out again. Finally, the egg was quickly placed on the mouth of the bottle. After a few seconds, the egg was pulled inside. From this, I can draw the conclusion that cooling air takes up less space, so the outside air pushes the egg in.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["This experiment is designed to show how air pressure can push an egg into a bottle.","First, the shell of the egg was removed.","After a few seconds, the egg was pulled inside.","From this, I can draw the conclusion that cooling air takes up less space."]'::jsonb, '[{"wrong":"The shell was remove.","correct":"The shell was removed.","note":"被动语态用 be + 过去分词,remove 要变 removed。"},{"wrong":"Hot water poured into the bottle.","correct":"Hot water was poured into the bottle.","note":"water 是动作承受者,描述步骤用被动 was poured。"},{"wrong":"This experiment is design to test air.","correct":"This experiment is designed to test air.","note":"is designed to 固定被动结构,design 要变 designed。"}]'::jsonb, '【实验报告结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U3', '{"title":"现在完成被动语态 have/has been done 速查","intro":"结构 = have/has + been + 过去分词。表示\"到现在为止\"某动作已经被完成,且对现在有影响。主语是动作的承受者。判断口诀:主语挨打(承受动作)+ 现在完成时间标志(already / so far / recently / since…)→ have/has been done。","table":{"headers":["对比项","形式 / 例句"],"rows":[["现在完成被动","have/has been + done:New parts have been printed.(部件已被打印)"],["现在完成主动","have/has + done:Scientists have printed new parts.(科学家已打印部件)"],["一般现在被动","am/is/are + done:The part is printed in a lab.(经常性事实)"],["一般过去被动","was/were + done:The part was printed last week.(过去某时)"]]},"specialRules":[{"rule":"主语单数用 has been done,复数/I/you/we/they 用 have been done","mark":"A house has been built. / Many cars have been made."},{"rule":"施动者用 by 引出,可省略","mark":"The robot has been fixed (by the students)."},{"rule":"时间标志定时态:already/so far/up to now/since/recently → 现在完成,不用 is done / was done","mark":"So far, no time machine has been invented."},{"rule":"主语后若还跟宾语,说明主语是发出者 → 改用主动,不用被动","mark":"Scientists have made parts.(✓主动)/ Scientists have been made parts.(✗)"}],"why":["选被动还是主动,先看主语:主语是\"做动作的人/物\"用主动 have done;主语是\"被动作影响的东西\"(后面常带 by …、且空后没有宾语)用被动 have been done。","选什么时态,看时间标志:有 already / so far / recently 等强调\"到现在\"的词,就用现在完成,而不是一般现在或一般过去。"],"gaokaoPoints":["语法填空/改错高频:给出动词原形,需根据主语单复数和语态填 has/have been + 过去分词。","易错点:把现在完成被动错写成现在完成主动(漏掉 been),或与一般过去被动(was/were done)混淆——靠时间标志区分。"],"examVsReal":[{"exam":"Much progress has been made in this field.(考试/书面)","real":"We''ve made a lot of progress here.(口语)","note":"考试爱考被动强调结果;日常口语常用主动、更直接。"},{"exam":"The work has been finished.(强调完成、不提是谁)","real":"I''ve finished the work.(口语点明施动者)","note":"被动多用于科技、报告等正式语体,隐去或弱化施动者。"}]}'::jsonb, 'fltrp');
